// Connecteur « KIM » : une ligne par PDF joint (lettre de médecin).
const sortie = [];
for (const { json: m } of $input.all()) {
  for (const pj of m.Attachments ?? []) {
    const estPdf = /pdf/i.test(pj.ContentType ?? '') || /\.pdf$/i.test(pj.FileName ?? '');
    if (!estPdf) continue;
    sortie.push({
      json: {
        id: m.ID,
        partId: pj.PartID,
        fileName: pj.FileName,
        from: m.From?.Address,
        expediteur: m.From?.Name || m.From?.Address,
        subject: m.Subject,
        date: m.Date,
      },
    });
  }
}
return sortie;

// Connecteur « KIM » : lettre de médecin (texte du PDF ou OCR) -> document de la collection « a_verifier ».
//
// Une lettre est TOUJOURS déposée dans « a_verifier » : tant qu'elle n'a pas été contrôlée (contradiction avec
// l'allergie, le traitement, la fonction rénale…), son contenu n'est pas présenté comme fiable.
// Rattachement au résident : le nom ET la date de naissance (jj.mm.aaaa) du courrier doivent correspondre à UN
// seul résident (les deux « Heinz Müller » ne se distinguent que par la date). Sinon on ne devine pas :
// la lettre reste sans patient_id, avec le motif identite_inconnue ou identite_ambigue.
const residents = $('Résidents').all().map((i) => i.json);
const pieces = $('Pièces jointes').all();
const norm = (s) => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const docs = [];
$input.all().forEach((item, i) => {
  const p = pieces[i].json;
  const texte = String(item.json.texte ?? '').trim();
  if (!texte) return;

  const t = norm(texte);
  const trouves = residents.filter((r) => t.includes(norm(r.nom)) && texte.includes(r.naissance));
  const base = {
    collection: 'a_verifier',
    source: 'kim',
    source_label: 'KIM (lettre de médecin)',
    // Référence stable (expéditeur + nom du fichier) : renvoyer le même courrier ne crée pas de doublon.
    source_ref: `kim/${p.from}/${p.fileName}`,
    type: 'lettre',
    titre: p.subject,
    expediteur: p.expediteur,
    statut: 'a_verifier',
    texte,
    date: new Date(p.date).toISOString(),
  };

  if (trouves.length === 1) {
    const r = trouves[0];
    docs.push({
      ...base,
      motif: 'lettre_a_verifier',
      patient_id: r.patient_id,
      chambre: r.chambre,
      patient_label: `${r.civilite} ${r.prenom} ${r.nom} (chambre ${r.chambre})`,
    });
  } else {
    docs.push({ ...base, motif: trouves.length === 0 ? 'identite_inconnue' : 'identite_ambigue' });
  }
});
return docs.map((json) => ({ json }));

// Courrier reçu – un élément par lettre PDF indexée (identifiée ou non).
const docs = $('Documents KIM').all().map((i) => i.json).filter((d) => d.source_ref);
return docs.map((d) => ({
  json: {
    source_ref: d.source_ref,
    titre: d.titre ?? 'Lettre de médecin',
    expediteur: d.expediteur ?? 'expéditeur inconnu',
    date: d.date,
    motif: d.motif,
    patient_id: d.patient_id ?? '',
    chambre: d.chambre ?? '',
    patient_label: d.patient_label ?? '',
  },
}));

// Courrier reçu – alerte d'un courrier RATTACHÉ à un résident. Le rapport des règles de contrôle (sans IA) donne la gravité :
// contradiction = rouge ; aucune contradiction = information (le courrier reste à valider par un soignant).
const lettres = $('Courriers à traiter').all().map((i) => i.json).filter((d) => d.patient_id);
const alertes = $input.all().map((item, i) => {
  const l = lettres[i];
  const r = item.json ?? {};
  const courrier = { titre: l.titre, expediteur: l.expediteur, date: l.date, ref: l.source_ref };
  const resident = l.patient_label.replace(/\s*\(chambre[^)]*\)\s*$/, '');
  const base = { resident, chambre: l.chambre, courrier, source: 'KIM (lettre de médecin)' };
  const contradictions = (Array.isArray(r.alertes) ? r.alertes : []).map((a) => String(a.message ?? '').slice(0, 300));
  if (!r.brouillon_id) {
    return {
      topic: `courrier/${l.source_ref}`, chambre: l.chambre, libelle: 'Courrier reçu : vérification impossible', patient_id: l.patient_id,
      faits: { ...base, gravite: 'attention', avertissement: 'La vérification automatique de ce courrier n\'a pas abouti. Ouvrez « Vérifier le document » pour la relancer.' },
    };
  }
  return {
    topic: `courrier/${l.source_ref}`,
    chambre: l.chambre,
    libelle: contradictions.length ? 'Contradiction dans un courrier' : 'Courrier à valider : aucune contradiction',
    patient_id: l.patient_id,
    faits: { ...base, gravite: contradictions.length ? 'rouge' : 'info', contradictions, brouillon_id: r.brouillon_id },
  };
});
return [{ json: { alertes } }];

// Courrier reçu – alerte d'un courrier NON rattaché : nom et date de naissance ne correspondent à aucun résident, ou à plusieurs.
// Le courrier reste dans « à vérifier », sans résident : on ne devine jamais.
const alertes = $input.all().map((i) => i.json).map((l) => ({
  topic: `courrier/${l.source_ref}`,
  chambre: '',
  libelle: 'Courrier non identifié',
  patient_id: '',
  faits: {
    gravite: 'attention',
    courrier: { titre: l.titre, expediteur: l.expediteur, date: l.date, ref: l.source_ref },
    avertissement: l.motif === 'identite_ambigue'
      ? 'Le nom et la date de naissance du courrier correspondent à plusieurs résidents : le courrier n\'est rattaché à personne.'
      : 'Le nom et la date de naissance du courrier ne correspondent à aucun résident : le courrier n\'est rattaché à personne.',
    source: 'KIM (lettre de médecin)',
  },
}));
return [{ json: { alertes } }];
